use genex::prelude::*;
use genex::render::Fog;

// Air is the look's fog, set once: genex.toml [render.look] fog_density / fog_height_falloff, or in code.
// A floor-hugging mist is the height falloff, not a translucent plane at knee height.
fn wire_air(game: &mut Game<super::World>) {
    game.render_settings(RenderConfig::from_build().fog(Fog::default().with_density(0.008).with_height(0.6, 0.0)));
}
